import org.w3c.dom.HTMLCanvasElement
import vision.gears.webgpumath.*
import kotlin.js.Date
import kotlin.js.json

class Scene (
  val device : GPUDevice,
  val targetFormat : String) {

  val vsTrafo = Shader(device, "trafo-vs.wgsl")
  val fsTextured = Shader(device, "textured-fs.wgsl")
  val vsQuad = Shader(device, "quad-vs.wgsl")
  val fsBackground = Shader(device, "background-fs.wgsl")
  val backgroundMaterial = Material(vsQuad, fsBackground)
  val skyCubeTexture = TextureCube(device,
      "media/posx512.jpg", "media/negx512.jpg",
      "media/posy512.jpg", "media/negy512.jpg",
      "media/posz512.jpg", "media/negz512.jpg"
    )
  init {
    backgroundMaterial["envTexture"]?.set( skyCubeTexture )
  }
  val quadGeometry = TexturedQuadGeometry(device)
  val backgroundMesh = Mesh(backgroundMaterial, quadGeometry)

  val slowpokeTexture = Texture2D(device, "media/slowpoke/YadonDh.png")
  val slowpokeEyeTexture = Texture2D(device, "media/slowpoke/YadonEyeDh.png")
  val slowpokeMaterial = Material(vsTrafo, fsTextured)
  init{
    slowpokeMaterial["colorTexture"]?.set(slowpokeTexture)
  }
  val slowpokeEyeMaterial = Material(vsTrafo, fsTextured)
  init{
    slowpokeEyeMaterial["colorTexture"]?.set(slowpokeEyeTexture)
  }
  val jsonLoader = JsonLoader()
  val slowpokeGeometries = jsonLoader.loadGeometries(device,
    "media/slowpoke/Slowpoke.json")
  val slowpokeMeshes = arrayOf(
    Mesh(slowpokeMaterial, slowpokeGeometries[0]),
    Mesh(slowpokeEyeMaterial, slowpokeGeometries[1]),
  )

  // The per-object data of all game objects is in one buffer: the "gameObjects" array of the shaders.
  val gameObjectGroup = InstanceGroup("gameObjects", 1024)
  val gameObjects = ArrayList<GameObject>()
  val avatar = GameObject(gameObjectGroup, *slowpokeMeshes)
  init{
    gameObjects.add(avatar)
  }

  val camera = PerspectiveCamera()

  val timeAtFirstFrame = Date().getTime()
  var timeAtLastFrame =  timeAtFirstFrame

  val depthFormat = "depth24plus"
  var depthTexture : GPUTexture? = null
  var frameCount = 0

  fun resize(canvas : HTMLCanvasElement) {
    camera.setAspectRatio(canvas.width.toFloat() / canvas.height.toFloat())

    // the depth buffer is ours to create, in the size of the canvas
    depthTexture?.destroy()
    depthTexture = device.createTexture(json(
      "size" to arrayOf(canvas.width, canvas.height),
      "format" to depthFormat,
      "usage" to GPUTextureUsage.RENDER_ATTACHMENT))
  }

  fun update(encoder : GPUCommandEncoder, target : GPUTextureView, keysPressed : Set<String>) {

    val timeAtThisFrame = Date().getTime()
    val dt = (timeAtThisFrame - timeAtLastFrame).toFloat() / 1000.0f
    val t  = (timeAtThisFrame - timeAtFirstFrame).toFloat() / 1000.0f
    timeAtLastFrame = timeAtThisFrame

    camera.move(dt, keysPressed)

    val spawn = ArrayList<GameObject>()
    val killList = ArrayList<GameObject>()
    gameObjects.forEach {
      if(!it.move(dt, t, keysPressed, gameObjects, spawn)){
        killList.add(it)
      }
    }
    killList.forEach{
      gameObjects.remove(it)
      it.release() // give its slot in the group back
    }
    spawn.forEach{ gameObjects.add(it) }

    gameObjects.forEach { it.update() }

    // Uniform data is uploaded once per frame, when first used:
    // all updates must be done before drawing starts.

    // set render target; clear the screen
    val pass = Pass(
      device,
      encoder.beginRenderPass(json(
        "colorAttachments" to arrayOf(json(
          "view" to target,
          "clearValue" to json("r" to 0.3, "g" to 0.0, "b" to 0.3, "a" to 1.0),
          "loadOp" to "clear",
          "storeOp" to "store")),
        "depthStencilAttachment" to json(
          "view" to depthTexture!!.createView(),
          "depthClearValue" to 1.0,
          "depthLoadOp" to "clear",
          "depthStoreOp" to "store"))),
      colorFormats = arrayOf(targetFormat),
      depthFormat = depthFormat,
      frame = frameCount++)

    backgroundMesh.draw(pass, 0, 1, camera)
    gameObjects.forEach { it.draw(pass, camera) }

    pass.encoder.end()
  }
}
